package com.eva.ro.contab.wms;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.IntFunction;

import com.eva.ro.contab.corelare.SetLista;
import com.eva.ro.contab.documente.Etichete;

/**
 * P01.C03.T0029 (P01.T355) A-1 (spec {@code 05_} §3.2) — regulile PURE ale notei WMS a setului: nota de ambalare (piesele din pozițiile
 * lui W → setul pe poziția L, pe versiunea {@code PP_Product_BOM_ID} a listei) și nota de dezambalare (setul de pe (L, versiune) → piesele
 * pe L). Fără bază și fără context: definiția setului e regula T354 ({@link SetLista#refuzDefinitie}, D-08-3), la care se adaugă doar
 * garda proprie a lotului ({@link #M_LOT}, D-04-7); validatorul cererii ({@link #refuzCerere}) e chemat înaintea primei scrieri (X137);
 * mișcările sunt construite în ordine crescătoare (piesă, poziție), deci rezultatul e determinist. Scrierea = {@code StocWms.inregistreaza}
 * (procesul {@code corelare/NotaSetWmsProces}), un singur apel pe notă; ordinea lacătelor între scriitori o dă {@code StocWms.cheiOrdonate}
 * (A-8, D-08-2), nu lacătul {@link #cheieLacat} (acesta serializează doar notele aceleiași perechi).
 */
public final class NotaSetWms {

    private NotaSetWms() {
    }

    /** Tipul notei; scris în {@code EVA_MiscareWms.EVA_TipMiscareWms} ca {@code TipMiscareWms.AMBALARE} / {@code DEZAMBALARE}. */
    public enum Tip {
        AMBALARE, DEZAMBALARE
    }

    public static final String R_FIRMA = "t355.refuz.firma", R_TIP = "t355.refuz.tip", R_CANTITATE = "t355.refuz.cantitate",
            R_POZITIE = "t355.refuz.pozitie", R_VERSIUNE = "t355.refuz.versiune", R_SET = "t355.refuz.set", R_PIESE = "t355.refuz.piese";
    /** Motivul propriu al definiției (D-04-7): o componentă a listei urmărită pe lot / serie (T354 refuză doar seria). */
    public static final String M_LOT = "t355.motiv.lot";

    /** Tipul implicit al dialogului: «Dezmembrari» ⇒ dezambalare, «Productie» ⇒ ambalare. */
    public static Tip tipImplicit(boolean dezmembrare) {
        return dezmembrare ? Tip.DEZAMBALARE : Tip.AMBALARE;
    }

    // ───────────────────────────────────────────── SQL (constante; citite de procesul din corelare)
    // P01.T355 D-11c-8: listele și rândurile definiției se citesc direct cu SetLista.SQL_LISTE / SQL_RANDURI (același pachet ca procesul);
    // aici rămân doar interogările proprii ale notei.

    /** Componentele versiunii urmărite pe lot / serie (garda {@link #M_LOT}); parametri: ad_client_id, pp_product_bom_id. */
    public static final String SQL_LOT = "SELECT count(*) FROM pp_product_bomline bl JOIN m_product cp ON cp.m_product_id=bl.m_product_id"
            + " AND cp.ad_client_id=bl.ad_client_id WHERE bl.ad_client_id=? AND bl.pp_product_bom_id=? AND bl.isactive='Y'"
            + " AND cp.m_attributeset_id IS NOT NULL AND cp.m_attributeset_id>0";
    /** Cantitatea rândului setului (firmă, L, set, asi 0, versiune) — pre-verificarea dezambalării, FĂRĂ blocare (§3.9). */
    public static final String SQL_SET = "SELECT COALESCE(SUM(Qty),0) FROM " + ModelWms.STOC
            + " WHERE AD_Client_ID=? AND M_Locator_ID=? AND M_Product_ID=? AND M_AttributeSetInstance_ID=0 AND PP_Product_BOM_ID=?";
    /** Pozițiile active ale lui W: aceeași interogare ca validatorul scrierii ({@code StocWms.DepozitBd}, o singură sursă). */
    public static final String SQL_LOCATORI_W = StocWms.DepozitBd.SQL_LOCATORI;
    /** Prioritățile pozițiilor lui W: aceeași interogare ca oglinda ({@code OglindaWms}, o singură sursă). */
    public static final String SQL_PRIORITATE = OglindaWms.SQL_PRIORITATE;
    /** Lacătul tranzacției (aceeași formă ca scrierea stocului). */
    public static final String SQL_LACAT = StocWms.DepozitBd.SQL_LACAT;

    /** Cheia lacătului notelor aceleiași perechi (firmă, W) — luată de proces ÎNAINTEA citirilor (INV2). */
    public static String cheieLacat(int client, int w) {
        return "eva_notasetwms:" + client + ":" + w;
    }

    // ───────────────────────────────────────────── definiția și cererea

    /**
     * Motivul pentru care setul nu se poate ambala / dezambala (cheia etichetei) sau {@code null}: întâi regula T354
     * ({@link SetLista#refuzDefinitie}, cheile {@code t354.motiv.*}, D-08-3 — nicio copie a regulii), apoi garda proprie
     * {@code cuLot > 0} ⇒ {@link #M_LOT} (D-04-7).
     */
    public static String refuzDefinitie(boolean isBom, boolean isStocked, String tip, int liste, List<SetLista.RandLista> r, int cuLot) {
        String m = SetLista.refuzDefinitie(isBom, isStocked, tip, liste, r);
        if (m != null)
            return m;
        return cuLot > 0 ? M_LOT : null;
    }

    /** Cererea notei: tipul, firma, W și «Expediere» ei, setul, k, poziția L, versiunea, sursa rândurilor (AD_PInstance). */
    public record Cerere(Tip tip, int client, int gestiuneWms, int locatorExpediere, int set, int k, int locator, int bom, int tabela,
            int record) {
    }

    /**
     * Validatorul cererii (X137), fiecare condiție singură, în ordine (X198): firma determinată; tipul; k întreg ≥ 1; poziția L a lui W
     * și nu «Expediere»; la dezambalare versiunea dată. {@code null} = permis.
     */
    public static String refuzCerere(Cerere c, Set<Integer> locatoriW) {
        if (c == null || c.client() <= 0)
            return R_FIRMA;
        if (c.tip() == null)
            return R_TIP;
        if (c.k() < 1)
            return R_CANTITATE;
        if (locatoriW == null || !locatoriW.contains(c.locator()) || c.locator() == c.locatorExpediere())
            return R_POZITIE;
        if (c.tip() == Tip.DEZAMBALARE && c.bom() <= 0)
            return R_VERSIUNE;
        return null;
    }

    /** Dezambalarea a k seturi de pe rândul (L, set, versiune): permisă ⇔ {@code Qty ≥ k}. */
    public static String refuzSet(BigDecimal qtyRand, int k) {
        if (qtyRand == null || qtyRand.compareTo(BigDecimal.valueOf(k)) < 0)
            return R_SET;
        return null;
    }

    // ───────────────────────────────────────────── piesele

    /**
     * P01.T355 D-11c-2 (MA-04): pozițiile din care se poate lua o piesă = copia hărții fără «Expediere» — SINGURUL loc al excluderii;
     * procesul o calculează o dată pe piesă, iar {@link #disponibil} (verificarea lipsei) și {@link #alocaPiese} (alocarea) lucrează pe
     * aceeași hartă, deci o piesă cu stoc doar în «Expediere» e refuzată la verificare și nu ajunge niciodată la o alocare incompletă.
     */
    public static Map<Integer, BigDecimal> faraExpediere(Map<Integer, BigDecimal> stocPePozitii, int locatorExpediere) {
        Map<Integer, BigDecimal> m = new LinkedHashMap<>(stocPePozitii == null ? Map.of() : stocPePozitii);
        m.remove(locatorExpediere);
        return m;
    }

    /** Disponibilul unei piese pe pozițiile date ({@link #faraExpediere}): suma cantităților pozitive. */
    public static BigDecimal disponibil(Map<Integer, BigDecimal> pozitii) {
        BigDecimal s = BigDecimal.ZERO;
        if (pozitii != null)
            for (Map.Entry<Integer, BigDecimal> e : pozitii.entrySet())
                if (e.getValue() != null && e.getValue().signum() > 0)
                    s = s.add(e.getValue());
        return s;
    }

    /**
     * Pozițiile din care se iau {@code necesar} bucăți ale unei piese, pe pozițiile date ({@link #faraExpediere}, aceeași hartă ca
     * {@link #disponibil}): {@link AlegerePozitii#alege}; suma alocată sub necesar ⇒ {@code null} (cu {@link #disponibil} ≥ necesar pe
     * aceeași hartă nu se întâmplă: {@code alege} ia pozitivele până la necesar).
     */
    public static List<AlegerePozitii.Alocare> alocaPiese(Map<Integer, BigDecimal> pozitii, Map<Integer, Integer> prioritate,
            BigDecimal necesar, AlegerePozitii.Ordine ordine) {
        List<AlegerePozitii.Alocare> l = AlegerePozitii.alege(pozitii == null ? Map.of() : pozitii, prioritate, necesar, ordine);
        BigDecimal s = BigDecimal.ZERO;
        for (AlegerePozitii.Alocare a : l)
            s = s.add(a.qty());
        return necesar == null || s.compareTo(necesar) < 0 ? null : l;
    }

    /**
     * Prima piesă (crescător pe {@code M_Product_ID}) cu disponibilul sub necesar ⇒ textul {@code t355.refuz.piese} (codul piesei,
     * lipsa); {@code null} = toate piesele ajung.
     */
    public static String lipsa(Map<Integer, BigDecimal> necesar, Map<Integer, BigDecimal> disponibil, IntFunction<String> cod) {
        for (Map.Entry<Integer, BigDecimal> e : new TreeMap<>(necesar).entrySet()) {
            BigDecimal d = disponibil == null || disponibil.get(e.getKey()) == null ? BigDecimal.ZERO : disponibil.get(e.getKey());
            if (d.compareTo(e.getValue()) < 0)
                return Etichete.t(R_PIESE, cod.apply(e.getKey()), e.getValue().subtract(d).stripTrailingZeros().toPlainString());
        }
        return null;
    }

    // ───────────────────────────────────────────── mișcările

    private static MiscareWms rand(Cerere c, TipMiscareWms t, int produs, BigDecimal qty, int de, int la, int bom) {
        return new MiscareWms(t, c.gestiuneWms(), produs, 0, qty, de, la, c.tabela(), c.record(), 0, 0, false, bom, BigDecimal.ZERO, 0);
    }

    /**
     * Nota de ambalare: pentru fiecare piesă (crescător), pentru fiecare alocare (crescător pe poziție) un rând {@code AMBALARE} care
     * scade piesa din poziție ({@code bom} 0); la final un rând {@code AMBALARE} al setului, k bucăți, pe L, pe versiunea {@code c.bom}.
     */
    public static List<MiscareWms> ambalare(Cerere c, Map<Integer, BigDecimal> bucati, Map<Integer, List<AlegerePozitii.Alocare>> alocari) {
        List<MiscareWms> l = new ArrayList<>();
        for (Integer p : new TreeMap<>(bucati).keySet()) {
            List<AlegerePozitii.Alocare> a = new ArrayList<>(alocari.get(p));
            a.sort(Comparator.comparingInt(AlegerePozitii.Alocare::locator));
            for (AlegerePozitii.Alocare x : a)
                l.add(rand(c, TipMiscareWms.AMBALARE, p, x.qty(), x.locator(), 0, 0));
        }
        l.add(rand(c, TipMiscareWms.AMBALARE, c.set(), BigDecimal.valueOf(c.k()), 0, c.locator(), c.bom()));
        return l;
    }

    /**
     * Nota de dezambalare: un rând {@code DEZAMBALARE} care scade k seturi de pe (L, {@code c.bom}), apoi pe fiecare piesă (crescător)
     * un rând {@code DEZAMBALARE} cu k × bucăți pe L ({@code bom} 0; Î-10, D-05a-3).
     */
    public static List<MiscareWms> dezambalare(Cerere c, Map<Integer, BigDecimal> bucati) {
        List<MiscareWms> l = new ArrayList<>();
        BigDecimal k = BigDecimal.valueOf(c.k());
        l.add(rand(c, TipMiscareWms.DEZAMBALARE, c.set(), k, c.locator(), 0, c.bom()));
        for (Map.Entry<Integer, BigDecimal> e : new TreeMap<>(bucati).entrySet())
            l.add(rand(c, TipMiscareWms.DEZAMBALARE, e.getKey(), k.multiply(e.getValue()), 0, c.locator(), 0));
        return l;
    }
}
