     */
    static final ThreadLocal<Boolean> JETON_ACTIVARE = new ThreadLocal<>();

    /** Rezultatul activării: perechea, dacă e nouă, rândurile ACTIVARE scrise, refuzul (textul tradus) sau null. */
    public record Rezultat(PerecheWms pereche, boolean noua, int randuriActivare, String refuz) {
    }

    /** O cantitate de pe G la activare: produsul, lotul, cantitatea, codul produsului (pentru lista refuzului). */
    public record StocInitial(int produs, int asi, BigDecimal qty, String cod) {
    }

    static final String R_DEJA = "t331.activare.deja", R_GV = "t331.activare.refuz.gv", R_NEGATIV = "t331.activare.refuz.negativ",
            R_TIP = "t331.activare.refuz.tip", R_LUNGIME = "t331.activare.refuz.lungime", R_CONCURENTA = "t331.pereche.refuz.concurenta", R_W_LEGATA = "t331.pereche.refuz.w_legata";

    static final String SQL_PERECHE = "SELECT AD_Client_ID, M_Warehouse_ID, EVA_GestiuneWms_ID, EVA_LocatorReceptie_ID,"
            + " EVA_LocatorExpediere_ID, EVA_LocatorNeamplasat_ID, EVA_DataActivare FROM " + ModelWms.PERECHE
            + " WHERE AD_Client_ID=? AND IsActive=?";
    static final String SQL_DUPA_G = SQL_PERECHE + " AND M_Warehouse_ID=?", SQL_DUPA_W = SQL_PERECHE + " AND EVA_GestiuneWms_ID=?";
    /** Rândul lui G, blocat (N-3a: a doua sesiune așteaptă, apoi vede perechea creată de prima). */
    static final String SQL_G_BLOCAT = "SELECT M_Warehouse_ID, " + TipGestiune.COL_TIP + " FROM M_Warehouse"
            + " WHERE AD_Client_ID=? AND M_Warehouse_ID=? FOR UPDATE";
