            + " FROM M_StorageOnHand s JOIN M_Locator l ON l.M_Locator_ID=s.M_Locator_ID AND l.AD_Client_ID=s.AD_Client_ID"
            + " JOIN M_Product p ON p.M_Product_ID=s.M_Product_ID"
