    }

    /** Cererea notei: tipul, firma, W și «Expediere» ei, setul, k, poziția L, versiunea, sursa rândurilor (AD_PInstance). */
    public record Cerere(Tip tip, int client, int gestiuneWms, int locatorExpediere, int set, int k, int locator, int bom, int tabela,
            int record) {
    }

    /**
     * Validatorul cererii (X137), fiecare condiție singură, în ordine (X198): firma determinată; tipul; k întreg ≥ 1; poziția L a lui W
     * și nu «Expediere»; la dezambalare versiunea dată. {@code null} = permis.
     */
    public static String refuzCerere(Cerere c, Set<Integer> locatoriW) {
