    }

    /** Disponibilul unei piese pe pozițiile date ({@link #faraExpediere}): suma cantităților pozitive. */
    public static BigDecimal disponibil(Map<Integer, BigDecimal> pozitii) {
        BigDecimal s = BigDecimal.ZERO;
        if (pozitii != null)
            for (Map.Entry<Integer, BigDecimal> e : pozitii.entrySet())
                if (e.getValue() != null && e.getValue().signum() > 0)
                    s = s.add(e.getValue());
        return s;
    }

    /**
     * Pozițiile din care se iau {@code necesar} bucăți ale unei piese, pe pozițiile date ({@link #faraExpediere}, aceeași hartă ca
     * {@link #disponibil}): {@link AlegerePozitii#alege}; suma alocată sub necesar ⇒ {@code null} (cu {@link #disponibil} ≥ necesar pe
     * aceeași hartă nu se întâmplă: {@code alege} ia pozitivele până la necesar).
     */
