/**
 * P01.C03.T0017 (P01.T331) A-6 (04_ F-5; 05_ §3.6) — alegerea pozițiilor lui W la ieșirea fără culegere / la culegere (comună cu T326);
 * PURĂ, «Expediere» exclusă de apelant. Pozițiile fără stoc pozitiv nu se aleg; ce nu se acoperă rămâne apelantului
 * ({@code cantitate − Σ alocări} = {@code EVA_CantitateLipsa}, Î-C-2).
 */
public final class AlegerePozitii {

    private AlegerePozitii() {
    }

    public enum Ordine {
        /** implicit = comportamentul de azi ({@code GeneratorDocumente.stocPeLocatii}: cantitatea descrescător, apoi locatorul). */
        CEL_MAI_MULT_INTAI,
        /** {@code M_Locator.PriorityNo} descrescător (sensul nativ al {@code MStorageOnHand.getWarehouse}), apoi ca mai sus. */
        PRIORITATE_POZITIE
    }

    public record Alocare(int locator, BigDecimal qty) {
    }

    /** PUR: comparatorul ordinii (expus ca testul să-l fixeze pe capete: egalitate de cantitate, egalitate de prioritate). */
    static Comparator<Map.Entry<Integer, BigDecimal>> ordine(Map<Integer, Integer> prioritate, Ordine o) {
        Comparator<Map.Entry<Integer, BigDecimal>> cant = Comparator.comparing(Map.Entry<Integer, BigDecimal>::getValue).reversed();
        Comparator<Map.Entry<Integer, BigDecimal>> c = o == Ordine.PRIORITATE_POZITIE
                ? Comparator.<Map.Entry<Integer, BigDecimal>>comparingInt(e -> prioritate == null ? 0 : prioritate.getOrDefault(e.getKey(), 0))
                        .reversed().thenComparing(cant)
                : cant;
        return c.thenComparing(Map.Entry::getKey);
    }

    public static List<Alocare> alege(Map<Integer, BigDecimal> stocPePozitii, Map<Integer, Integer> prioritate, BigDecimal cantitate,
            Ordine ordine) {
        List<Alocare> l = new ArrayList<>();
        if (stocPePozitii == null || cantitate == null || cantitate.signum() <= 0)
            return l;
        List<Map.Entry<Integer, BigDecimal>> poz = new ArrayList<>();
        for (Map.Entry<Integer, BigDecimal> e : stocPePozitii.entrySet())
            if (e.getValue() != null && e.getValue().signum() > 0)
                poz.add(e);
        poz.sort(ordine(prioritate, ordine == null ? Ordine.CEL_MAI_MULT_INTAI : ordine));
        BigDecimal rest = cantitate;
        for (Map.Entry<Integer, BigDecimal> e : poz) {
            if (rest.signum() <= 0)
                break;
            BigDecimal ia = rest.min(e.getValue());
            l.add(new Alocare(e.getKey(), ia));
            rest = rest.subtract(ia);
        }
        return l;
    }
}

